#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 200;
const int MAXM = 100000;
const int INF = 300000000;

int maze_map[20][20];
int adjacency[MAXN][MAXN];
int n, total_nodes, t;
string input_line;
int hu_points[MAXN][3], re_points[MAXN][3];
int zr, zc;
int cx, cy;
int dir_moves[4][2] = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

int getNodeIndex(int r, int c) {
    if (r > 0 && r <= n && c > 0 && c <= n && maze_map[r][c] != -1)
        return (r - 1) * n + c;
    return -1;
}

void initializeGraph() {
    total_nodes = n * n;
    memset(adjacency, -1, sizeof(adjacency));
    for (int r1 = 1; r1 <= n; r1++) {
        for (int c1 = 1; c1 <= n; c1++) {
            if (maze_map[r1][c1] == -1) continue;
            int p1 = (r1 - 1) * n + c1;
            adjacency[p1][p1] = 0;
            for (int i = 0; i < 4; i++) {
                int r2 = r1 + dir_moves[i][0];
                int c2 = c1 + dir_moves[i][1];
                if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && maze_map[r2][c2] != -1) {
                    int p2 = (r2 - 1) * n + c2;
                    adjacency[p1][p2] = 1;
                }
            }
        }
    }
}

int dist_array[MAXN];
int q_array[MAXM];

void computeShortestPaths() {
    int front = 0, rear = 1;
    for (int i = 1; i <= total_nodes; i++) dist_array[i] = INF;
    int start_node = (zr - 1) * n + zc;
    dist_array[start_node] = 0;
    q_array[0] = start_node;
    while (front < rear) {
        int u = q_array[front++];
        for (int v = 1; v <= total_nodes; v++) {
            if (adjacency[u][v] == 1 && dist_array[v] > dist_array[u] + 1) {
                dist_array[v] = dist_array[u] + 1;
                q_array[rear++] = v;
            }
        }
    }
}

void allPairsFloyd() {
    for (int k = 1; k <= total_nodes; k++) {
        for (int i = 1; i <= total_nodes; i++) {
            for (int j = 1; j <= total_nodes; j++) {
                if (adjacency[i][k] != -1 && adjacency[k][j] != -1) {
                    if (adjacency[i][j] == -1 || adjacency[i][j] > adjacency[i][k] + adjacency[k][j]) {
                        adjacency[i][j] = adjacency[i][k] + adjacency[k][j];
                    }
                }
            }
        }
    }
}

struct Edge {
    int from, to, capacity, next;
};

vector<Edge> flowEdges;
int head[MAXN], edgeCount;
int sourceNode, sinkNode;

void addFlowEdge(int u, int v, int cap) {
    flowEdges.push_back({u, v, cap, head[u]});
    head[u] = (int)flowEdges.size() - 1;
    flowEdges.push_back({v, u, 0, head[v]});
    head[v] = (int)flowEdges.size() - 1;
}

int level[MAXN];

bool buildLevelGraph() {
    memset(level, -1, sizeof(level));
    level[sourceNode] = 0;
    queue<int> q;
    q.push(sourceNode);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = flowEdges[i].next) {
            int v = flowEdges[i].to;
            if (flowEdges[i].capacity > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[sinkNode] != -1;
}

int ptr[MAXN];

int sendFlow(int u, int flow) {
    if (u == sinkNode) return flow;
    for (int &i = ptr[u]; i != -1; i = flowEdges[i].next) {
        int v = flowEdges[i].to;
        if (flowEdges[i].capacity > 0 && level[v] == level[u] + 1) {
            int pushed = sendFlow(v, min(flow, flowEdges[i].capacity));
            if (pushed > 0) {
                flowEdges[i].capacity -= pushed;
                flowEdges[i ^ 1].capacity += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int totalFlow = 0;
    while (buildLevelGraph()) {
        for (int i = 0; i <= total_nodes + 1; i++) ptr[i] = head[i];
        while (int pushed = sendFlow(sourceNode, INF))
            totalFlow += pushed;
    }
    return totalFlow;
}

int solve() {
    maze_map[zr][zc] = 0;
    initializeGraph();
    computeShortestPaths();
    maze_map[zr][zc] = -1;
    initializeGraph();
    allPairsFloyd();
    flowEdges.clear();
    memset(head, -1, sizeof(head));
    edgeCount = 0;
    sourceNode = 0;
    sinkNode = cx + cy + 1;
    for (int i = 1; i <= cx; i++) {
        addFlowEdge(sourceNode, i, hu[i][2]);
    }
    for (int i = 1; i <= cy; i++) {
        addFlowEdge(cx + i, sinkNode, re[i][2]);
    }
    int p = (zr - 1) * n + zc;
    for (int i = 1; i <= cx; i++) {
        for (int j = 1; j <= cy; j++) {
            int p1 = (hu[i][0] - 1) * n + hu[i][1];
            int p2 = (re[j][0] - 1) * n + re[j][1];
            if (adjacency[p1][p2] != -1 && adjacency[p1][p2] <= t && adjacency[p1][p2] < dist_array[p2]) {
                addFlowEdge(i, cx + j, INF);
            } else if (adjacency[p1][p2] != -1 && adjacency[p1][p2] <= t && adjacency[p1][p2] == dist_array[p2]) {
                for (int z = 0; z < 4; z++) {
                    int rr = re[j][0] + dir_moves[z][0];
                    int cc = re[j][1] + dir_moves[z][1];
                    int pp = getNodeIndex(rr, cc);
                    if (pp != -1) {
                        if (adjacency[p1][pp] == adjacency[p1][p2] - 1 && adjacency[p1][pp] < dist_array[pp]) {
                            addFlowEdge(i, cx + j, INF);
                        }
                    }
                }
            }
        }
    }
    return maxFlow();
}

int main() {
    cin >> n >> t;
    cx = cy = 0;
    memset(maze_map, 0, sizeof(maze_map));
    for (int i = 1; i <= n; i++) {
        cin >> input_line;
        for (int j = 0; j < n; j++) {
            if (input_line[j] == 'Y') maze_map[i][j + 1] = -1;
            else if (input_line[j] == 'Z') {
                zr = i; zc = j + 1;
                maze_map[i][j + 1] = -1;
            } else if (input_line[j] > '0' && input_line[j] <= '9') {
                hu[++cx][0] = i;
                hu[cx][1] = j + 1;
                hu[cx][2] = input_line[j] - '0';
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cin >> input_line;
        for (int j = 0; j < n; j++) {
            if (input_line[j] > '0' && input_line[j] <= '9') {
                re[++cy][0] = i;
                re[cy][1] = j + 1;
                re[cy][2] = input_line[j] - '0';
            }
        }
    }
    cout << solve() << endl;
    return 0;
}
